CREATE TABLE IF NOT EXISTS users(id bigserial PRIMARY KEY,name varchar(255) NOT NULL,email varchar(255) UNIQUE NOT NULL,password varchar(255) NOT NULL,email_verified_at timestamp,created_at timestamp,updated_at timestamp);
CREATE TABLE IF NOT EXISTS dictionary_entries(id bigserial PRIMARY KEY,word varchar(255) UNIQUE NOT NULL,phonetic varchar(120),audio_url text,source varchar(40) NOT NULL DEFAULT 'user_save',is_curated boolean NOT NULL DEFAULT false,save_count integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_meanings(id bigserial PRIMARY KEY,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id) ON DELETE CASCADE,part_of_speech varchar(40),definition text NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_examples(id bigserial PRIMARY KEY,dictionary_meaning_id bigint NOT NULL REFERENCES dictionary_meanings(id) ON DELETE CASCADE,example text NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_synonyms(id bigserial PRIMARY KEY,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id) ON DELETE CASCADE,dictionary_meaning_id bigint REFERENCES dictionary_meanings(id) ON DELETE CASCADE,term varchar(120) NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_antonyms(id bigserial PRIMARY KEY,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id) ON DELETE CASCADE,dictionary_meaning_id bigint REFERENCES dictionary_meanings(id) ON DELETE CASCADE,term varchar(120) NOT NULL,position integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL,updated_at timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS vocabularies(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,dictionary_entry_id bigint NOT NULL REFERENCES dictionary_entries(id),times_quizzed integer NOT NULL DEFAULT 0,last_quizzed_at timestamp,last_correct_at timestamp,created_at timestamp NOT NULL,updated_at timestamp NOT NULL,UNIQUE(user_id,dictionary_entry_id));